  summary: "Raise each scf.for over tensors whose body only computes to a linalg.generic"
  dependentDialects = ["::mlir::linalg::LinalgDialect", "::mlir::tensor::TensorDialect", "::mlir::arith::ArithDialect"]
  statistics: numTabulates "tabulates", numReductions "reductions", numInterchanged "interchanged", numReads "reads"
